package dev.ledgerbank.rail;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="external_accounts") class ExternalAccount{@Id UUID id;@Column(name="user_subject")UUID userSubject;@Column(name="institution_name")String institutionName;@Column(name="masked_number",length=4)String maskedNumber;String status;@Column(name="created_at")Instant createdAt;protected ExternalAccount(){}ExternalAccount(UUID user,String institution,String last4,Instant now){id=UUID.randomUUID();userSubject=user;institutionName=institution;maskedNumber=last4;status="VERIFIED";createdAt=now;}}
@Entity @Table(name="ach_transfers",uniqueConstraints=@UniqueConstraint(columnNames={"user_subject","idempotency_key"}))class AchTransfer{@Id UUID id;@Column(name="user_subject")UUID userSubject;@Column(name="ledger_account_id")UUID ledgerAccountId;@Column(name="external_account_id")UUID externalAccountId;String direction;@Column(name="amount_minor")long amountMinor;@Column(length=3)String currency;String scenario;String status;@Column(name="journal_id")UUID journalId;@Column(name="settlement_batch_id")UUID settlementBatchId;@Column(name="idempotency_key")String idempotencyKey;@Column(name="request_fingerprint",length=64)String fingerprint;@Column(name="correlation_id")String correlationId;@Column(name="next_transition_at")Instant nextTransitionAt;@Column(name="failure_detail")String failureDetail;@Column(name="created_at")Instant createdAt;@Column(name="updated_at")Instant updatedAt;@Version long version;protected AchTransfer(){}AchTransfer(UUID user,UUID ledger,UUID external,String direction,long amount,String scenario,String key,String fingerprint,String cid,Instant now){id=UUID.randomUUID();userSubject=user;ledgerAccountId=ledger;externalAccountId=external;this.direction=direction;amountMinor=amount;currency="USD";this.scenario=scenario;status=direction.equals("WITHDRAWAL")?"PROCESSING":"INITIATED";idempotencyKey=key;this.fingerprint=fingerprint;correlationId=cid;createdAt=updatedAt=now;nextTransitionAt=now;}}
